<?php
define('MOD', 998244353);

function modpow($a, $b, $mod) {
    $result = 1;
    $a = $a % $mod;
    while ($b > 0) {
        if ($b % 2 == 1) {
            $result = ($result * $a) % $mod;
        }
        $b = intdiv($b, 2);
        $a = ($a * $a) % $mod;
    }
    return $result;
}

function modinv($a, $mod) {
    return modpow($a, $mod - 2, $mod);
}

// Precompute factorials and inverse factorials up to maxN
function precompute_factorials($maxN) {
    $fact = array_fill(0, $maxN + 1, 1);
    $inv_fact = array_fill(0, $maxN + 1, 1);

    for ($i = 1; $i <= $maxN; $i++) {
        $fact[$i] = ($fact[$i - 1] * $i) % MOD;
    }

    $inv_fact[$maxN] = modinv($fact[$maxN], MOD);
    for ($i = $maxN - 1; $i >= 0; $i--) {
        $inv_fact[$i] = ($inv_fact[$i + 1] * ($i + 1)) % MOD;
    }

    return [$fact, $inv_fact];
}

function nCr($n, $r, $fact, $inv_fact) {
    if ($r < 0 || $r > $n) return 0;
    return ($fact[$n] * $inv_fact[$r] % MOD) * $inv_fact[$n - $r] % MOD;
}

// Count number of non-negative integer solutions to x1 + x2 + ... + xk = n
function count_solutions($n, $k) {
    // Number of non-negative integer solutions to x1 + ... + xk = n is C(n + k - 1, k - 1)
    if ($n < 0 || $k <= 0) return 0;
    if ($k == 1) return 1;
    return nCr($n + $k - 1, $k - 1, $GLOBALS['fact'], $GLOBALS['inv_fact']);
}

// Count number of non-negative integer solutions to x1 + x2 + ... + xk = n where xi >= lower_bound_i
// Here we only have a lower bound on x1 (Hasan's score)
function count_with_lower_bound($n, $k, $lower_bound) {
    // x1 >= lower_bound, x2...xk >= 0
    // Let y1 = x1 - lower_bound >= 0
    // y1 + x2 + ... + xk = n - lower_bound
    if ($n < $lower_bound) return 0;
    return count_solutions($n - $lower_bound, $k);
}

