    // a1 > a2, a1 > a3, ..., a1 > ap
    // Let a1 = x. Then x >= r, x <= s (since others are >= 0)
    // For each x, we need to count the number of (a2, ..., ap) such that:
    //   a2 + ... + ap = s - x
    //   ai < x for all i = 2, ..., p
    //   ai >= 0

    $total = 0;
    $max_x = $s; // x can be at most s (when others are 0)

    for ($x = $r; $x <= $max_x; $x++) {
        $remaining = $s - $x;
        if ($remaining < 0) break;

        // Count number of non-negative integer solutions to a2 + ... + ap = remaining
        // with each ai < x (i.e., ai <= x - 1)
        // This is a bounded composition problem.
        // Number of solutions to a2 + ... + ap = remaining with 0 <= ai <= x-1
        // = number of non-negative solutions with upper bound x-1

        // Use inclusion-exclusion or DP. Since p <= 100 and s <= 5000, we can use DP.
        // But doing DP for each x would be too slow. Let's think differently.

        // Actually, we can precompute or use a formula.
        // The number of non-negative integer solutions to a2 + ... + ap = remaining
        // with each ai <= x - 1 is:
        // sum_{j=0}^{floor(remaining / x)} (-1)^j * C(p-1, j) * C(remaining - j*x + p - 2, p - 2)
        // This is by inclusion-exclusion.

        $num_vars = $p - 1; // number of variables a2, ..., ap
        if ($num_vars == 0) {
            // p = 1, only Hasan. He always wins if s >= r (which is given).
            if ($remaining == 0) {
                $total = ($total + 1) % MOD;
