        // Number of solutions = sum_{j=0}^{floor(remaining / (upper+1))} (-1)^j * C(num_vars, j) * C(remaining - j*(upper+1) + num_vars - 1, num_vars - 1)
        // Note: upper+1 = x

        $max_j = intdiv($remaining, $x); // since upper+1 = x
