        // If x-1 < 0, i.e., x=0, then count_less = 0 (unless T=0 and p-1=0, but p>=1)
        // Actually if x=0, then x-1 = -1, so no bi can be <= -1, so count_less = 0.

        $U = $x - 1;
        $n = $p - 1;

        if ($n == 0) {
            // Only one player (Hasan), so he always wins
            $numerator = ($numerator + 1) % $MOD;
            continue;
        }

        // Compute D(n, T, U) using DP
        // dp[j] = number of ways for current number of players to sum to j
        $dp = array_fill(0, $T + 1, 0);
        $dp[0] = 1;

        for ($i = 1; $i <= $n; $i++) {
            $newDp = array_fill(0, $T + 1, 0);
            // Use prefix sum optimization
            $prefix = array_fill(0, $T + 2, 0);
            $prefix[0] = $dp[0];
            for ($j = 1; $j <= $T; $j++) {
                $prefix[$j] = ($prefix[$j - 1] + $dp[$j]) % $MOD;
            }
            for ($j = 0; $j <= $T; $j++) {
                $lo = max(0, $j - $U);
                $hi = $j;
                if ($lo <= $hi) {
                    $val = $prefix[$hi];
                    if ($lo > 0) {
                        $val = ($val - $prefix[$lo - 1] + $MOD) % $MOD;
                    }
                    $newDp[$j] = $val;
                }
            }
            $dp = $newDp;
        }

        $count_less = $dp[$T];

        // Now compute B(x, T) = sum_{k=1}^{n} C(n, k) * D(n-k, T - k*x, x-1) * inv(k+1)
        $B = 0;
        for ($k = 1; $k <= $n; $k++) {
            $remaining = $T - $k * $x;
            if ($remaining < 0) break;

            $nRem = $n - $k;
            if ($nRem == 0) {
                $dVal = ($remaining == 0) ? 1 : 0;
            } else {
                // Compute D(nRem, remaining, x-1)
                $dp2 = array_fill(0, $remaining + 1, 0);
                $dp2[0] = 1;
                for ($i = 1; $i <= $nRem; $i++) {
                    $newDp2 = array_fill(0, $remaining + 1, 0);
                    $prefix2 = array_fill(0, $remaining + 2, 0);
                    $prefix2[0] = $dp2[0];
                    for ($j = 1; $j <= $remaining; $j++) {
                        $prefix2[$j] = ($prefix2[$j - 1] + $dp2[$j]) % $MOD;
                    }
                    for ($j = 0; $j <= $remaining; $j++) {
                        $lo2 = max(0, $j - $U);
                        $hi2 = $j;
                        if ($lo2 <= $hi2) {
                            $val2 = $prefix2[$hi2];
                            if ($lo2 > 0) {
                                $val2 = ($val2 - $prefix2[$lo2 - 1] + $MOD) % $MOD;
                            }
                            $newDp2[$j] = $val2;
                        }
                    }
                    $dp2 = $newDp2;
                }
                $dVal = $dp2[$remaining];
            }

            $comb = nCr($n, $k, $fact, $invFact, $MOD);
            $invK1 = modInverse($k + 1, $MOD);
            $term = $comb * $dVal % $MOD * $invK1 % $MOD;
            $B = ($B + $term) % $MOD;
        }

        $Sx = ($count_less + $B) % $MOD;
        $numerator = ($numerator + $Sx) % $MOD;
    }

    $denominator = $total;
    $answer = $numerator * modInverse($denominator, $MOD) % $MOD;

    echo $answer . "\n";
}

