<?php

define('MOD', 998244353);

function modPow($base, $exp, $mod) {
    $result = 1;
    $base = $base % $mod;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = ($result * $base) % $mod;
        }
        $exp = intdiv($exp, 2);
        $base = ($base * $base) % $mod;
    }
    return $result;
}

function modInverse($a, $mod) {
    return modPow($a, $mod - 2, $mod);
}

function solve() {
    $line = trim(fgets(STDIN));
