        $limit = intdiv($n, $maxVal + 1);
        for ($j = 0; $j <= $limit; $j++) {
            $remaining = $n - $j * ($maxVal + 1);
            if ($remaining < 0) break;
            $term = comb($m, $j, $fact, $invFact, $mod) * comb($remaining + $m - 1, $m - 1, $fact, $invFact, $mod) % $mod;
            if ($j % 2 == 0) {
                $result = ($result + $term) % $mod;
            } else {
                $result = ($result - $term + $mod) % $mod;
            }
        }
        return $result;
    }

    // Total number of valid states
    $totalStates = 0;
    for ($a1 = $r; $a1 <= $s; $a1++) {
        $remaining = $s - $a1;
        if ($remaining < 0) break;
        if ($p == 1) {
            $ways = ($remaining == 0) ? 1 : 0;
        } else {
            $ways = comb($remaining + $p - 2, $p - 2, $fact, $invFact, MOD);
        }
        $totalStates = ($totalStates + $ways) % MOD;
    }

    if ($totalStates == 0) {
        echo 0 . "\n";
        return;
    }

    // Now compute the sum of win probabilities over all valid states.
    $winSum = 0;

    for ($a1 = $r; $a1 <= $s; $a1++) {
        $remaining = $s - $a1;
        if ($remaining < 0) break;

        if ($p == 1) {
            // Only Hasan, he always wins
            if ($remaining == 0) {
                $winSum = ($winSum + 1) % MOD;
            }
            continue;
        }

        // Case 1: a1 > all other ai
        // Other players must have scores in [0, a1 - 1]
        $strictlyGreater = countBounded($remaining, $p - 1, $a1 - 1, $fact, $invFact, MOD);
        $winSum = ($winSum + $strictlyGreater) % MOD;

        // Case 2: a1 == max(ai for i>=2)
        // For k = 1 to p-1 (number of other players with score exactly a1)
        // Note: k=0 is already covered in Case 1 (where all others < a1)
        for ($k = 1; $k <= $p - 1; $k++) {
            // Choose k players out of p-1 to have score a1
            $chooseK = comb($p - 1, $k, $fact, $invFact, MOD);
            // The remaining p-1-k players must have scores in [0, a1-1]
            // Their sum must be: remaining - k * a1
            $remSum = $remaining - $k * $a1;
            if ($remSum < 0) continue;
            $numRemaining = $p - 1 - $k;
            if ($numRemaining == 0) {
                $ways = ($remSum == 0) ? 1 : 0;
            } else {
                $ways = countBounded($remSum, $numRemaining, $a1 - 1, $fact, $invFact, MOD);
            }
            if ($ways == 0) continue;
            // Hasan's win probability in each such state is 1/(k+1)
            $prob = modInverse($k + 1, MOD);
            $contribution = $chooseK * $ways % MOD * $prob % MOD;
            $winSum = ($winSum + $contribution) % MOD;
        }
    }

    $answer = $winSum * modInverse($totalStates, MOD) % MOD;
    echo $answer . "\n";
}

