    // Wait, the upper bound is x-1, so the number of solutions to sum = S with 0 <= a_i <= U is:
    // Sum_{j=0}^{floor(S/(U+1))} (-1)^j * C(n, j) * C(S - j*(U+1) + n - 1, n - 1)
    // Here n = p-1, S = s - x, U = x - 1, so U+1 = x.
    // U(x) = Sum_{j=0}^{floor((s-x)/x)} (-1)^j * C(p-1, j) * C(s - x - j*x + p - 2, p - 2)
    //
    // T(x, k): choose k players out of p-1 to have score x: C(p-1, k).
    // The remaining p-1-k players must have scores in [0, x-1] and sum to s - x - k*x.
    // So T(x, k) = C(p-1, k) * [number of solutions to sum = s - x - k*x with p-1-k variables in [0, x-1]]
    // = C(p-1, k) * Sum_{j=0}^{floor((s-x-k*x)/(x))} (-1)^j * C(p-1-k, j) * C(s - x - k*x - j*x + p - 1 - k - 1, p - 1 - k - 1)
    // = C(p-1, k) * Sum_{j=0}^{floor((s-x-k*x)/x)} (-1)^j * C(p-1-k, j) * C(s - x - (k+1)*j*x + p - 2 - k, p - 2 - k)
    //
    // This is computable. The inner sum has at most (s-x)/(k+1) + 1 terms, which is small.
    //
    // Let's implement this.
    //
    // Precompute factorials and inverse factorials up to N = s + p + 100.
    // N = 5000 + 100 + 100 = 5200.

    $N = $s + $p + 100;
    $fact = array_fill(0, $N + 1, 1);
    $invFact = array_fill(0, $N + 1, 1);

    for ($i = 1; $i <= $N; $i++) {
        $fact[$i] = ($fact[$i - 1] * $i) % MOD;
    }
    $invFact[$N] = modPow($fact[$N], MOD - 2, MOD);
    for ($i = $N; $i >= 1; $i--) {
        $invFact[$i - 1] = ($invFact[$i] * $i) % MOD;
    }

    function comb($n, $k, $fact, $invFact) {
        if ($k < 0 || $k > $n || $n < 0) return 0;
        return ($fact[$n] * $invFact[$k] % MOD) * $invFact[$n - $k] % MOD;
    }

    $total = comb($s - $r + $p - 1, $p - 1, $fact, $invFact);

    $numerator = 0;

    for ($x = $r; $x <= $s; $x++) {
        $remaining = $s - $x;
        if ($remaining < 0) continue;

        // U(x): all other players have score < x
        $u = 0;
        $maxJ = intdiv($remaining, $x);
        for ($j = 0; $j <= $maxJ; $j++) {
            $term = comb($p - 1, $j, $fact, $invFact);
            $inner = $remaining - $j * $x + $p - 2;
            if ($inner < $p - 2) continue;
            $c = comb($inner, $p - 2, $fact, $invFact);
            $val = ($term * $c) % MOD;
            if ($j % 2 == 1) {
                $u = ($u - $val + MOD) % MOD;
            } else {
                $u = ($u + $val) % MOD;
            }
        }
        $numerator = ($numerator + $u) % MOD;

        // T(x, k) for k = 1 to p-1
        for ($k = 1; $k <= $p - 1; $k++) {
            $rem2 = $remaining - $k * $x;
            if ($rem2 < 0) break;

            $n2 = $p - 1 - $k;
            if ($n2 < 0) continue;

            $t = 0;
            $maxJ2 = intdiv($rem2, $x);
            for ($j = 0; $j <= $maxJ2; $j++) {
                $term = comb($n2, $j, $fact, $invFact);
                $inner = $rem2 - $j * $x + $n2 - 1;
                if ($inner < $n2 - 1) continue;
                $c = comb($inner, $n2 - 1, $fact, $invFact);
                $val = ($term * $c) % MOD;
                if ($j % 2 == 1) {
                    $t = ($t - $val + MOD) % MOD;
                } else {
                    $t = ($t + $val) % MOD;
                }
            }

            $t = ($t * comb($p - 1, $k, $fact, $invFact)) % MOD;
            $invK1 = modInverse($k + 1, MOD);
            $contribution = ($t * $invK1) % MOD;
            $numerator = ($numerator + $contribution) % MOD;
        }
    }

    $numerator = ($numerator + MOD) % MOD;
    $answer = ($numerator * modInverse($total, MOD)) % MOD;

    echo $answer . "\n";
}

solve();
